Rule.fixtext:
Edit or add the following line in /etc/default/grub: GRUB_CMDLINE_LINUX_DEFAULT="security=selinux selinux=1" Note: Other parameters may be listed Run the following command to remove the selinux=0 and enforcing=0 parameters if they were created by the grub2-mkconfig command: # grep -Prsq -- '^\h*([^#
]+\h+)?kernelopts=([^#
]+\h+)?(selinux|enforcing)=0 ' /boot/grub2 /boot/efi && grub2-mkconfig -o "$(grep -Prl -- '\h*([^#
]+\h+)?kernelopts=([^#
]+\h+)?(selinux|enforcing)=0 ' /boot/grub2 /boot/efi)" Run the following command to import the changes into the main configuration file: # grub2-mkconfig -o /boot/grub2/grub.cfg

Create or modify a file ending in.conf in the /etc/security/pwquality.conf.d/ directory add or modify the following line to set difok to 2 or more. Ensure setting conforms to local site policy:
difok = 2
Example
#!/usr/bin/env bash
{
sed -ri 's/^\s*difok\s*=/# &/' /etc/security/pwquality.conf 2>/dev/null
[ ! -d /etc/security/pwquality.conf.d/ ] && mkdir
/etc/security/pwquality.conf.d/
printf '\n%s' "difok = 2" > /etc/security/pwquality.conf.d/50-pwdifok.conf
}

Create or modify a file ending in.conf in the /etc/security/pwquality.conf.d/ directory and add or modify the following line to set the enforce_for_root option:
enforce_for_root
Example:
#!/usr/bin/env bash
{
[ ! -d /etc/security/pwquality.conf.d/ ] && mkdir
/etc/security/pwquality.conf.d/
printf '\n%s\n' "enforce_for_root" > /etc/security/pwquality.conf.d/50-
pwroot.conf
}

Run the following command to set the shell for any service accounts returned by the audit to nologin:
# usermod -s $(command -v nologin) <user>
Example script:
#!/usr/bin/env bash
{
l_valid_shells="^($(awk -F\/ '($NF != "nologin" && $NF != "false")
{print}' /etc/shells | sed -rn '/^\//{s,/,\\\\/,g;p}' | paste -s -d '|' -
))$"
awk -v pat="$l_valid_shells" -F:
'($1!~/^(root|halt|sync|shutdown|nfsnobody)$/ && ($3<'"$(awk
'/^\s*UID_MIN/{print $2}' /etc/login.defs)"' || $3 == 65534) && $(NF) ~ pat)
{system ("usermod -s '"$(command -v nologin)"' " $1)}' /etc/passwd
}

check.check-content:
Run the following command to verify system accounts, except for root, halt, sync, shutdown or nfsnobody, do not have a valid login shell:
#!/usr/bin/env bash
{
l_valid_shells="^($(awk -F\/ '($NF != "nologin" && $NF != "false")
{print}' /etc/shells | sed -rn '/^\//{s,/,\\\\/,g;p}' | paste -s -d '|' -
))$"
awk -v pat="$l_valid_shells" -F:
'($1!~/^(root|halt|sync|shutdown|nfsnobody)$/ && ($3<'"$(awk
'/^\s*UID_MIN/{print $2}' /etc/login.defs)"' || $3 == 65534) && $(NF) ~ pat)
{print "Service account: \"" $1 "\" has a valid shell: " $7}' /etc/passwd
}
Nothing should be returned Internal Only - General

Rule.fixtext:
Run the following command to lock any non-root accounts without a valid login shell returned by the audit:
# usermod -L <user>
Example script::
#!/usr/bin/env bash
{
l_valid_shells="^($(awk -F\/ '($NF != "nologin" && $NF != "false")
{print}' /etc/shells | sed -rn '/^\//{s,/,\\\\/,g;p}' | paste -s -d '|' -
))$"
while IFS= read -r l_user; do
passwd -S "$l_user" | awk '$2 !~ /^L/ {system ("usermod -L " $1)}'
done < <(awk -v pat="$l_valid_shells" -F: '($1 != "root" && $(NF) !~ pat)
{print $1}' /etc/passwd)
}

check.check-content:
Run the following script to verify all non-root accounts without a valid login shell are locked.
#!/usr/bin/env bash
{
l_valid_shells="^($(awk -F\/ '($NF != "nologin" && $NF != "false")
{print}' /etc/shells | sed -rn '/^\//{s,/,\\\\/,g;p}' | paste -s -d '|' -
))$"
while IFS= read -r l_user; do
passwd -S "$l_user" | awk '$2 !~ /^L/ {print "Account: \"" $1 "\" does
not have a valid login shell and is not locked"}'
done < <(awk -v pat="$l_valid_shells" -F: '($1 != "root" && $(NF) !~ pat)
{print $1}' /etc/passwd)
}
Nothing should be returned Internal Only - General

Note: The -w option is deprecated and the rule should be updated in accordance with the Remediation Procedure. 1. Run the following command to verify a rule exists in the running configuration: # auditctl -l | grep -Ps -- '^\h*[^#
]+\h*/usr/bin/kmod' Verify the output includes: -a always,exit -F path=/usr/bin/kmod -F perm=x -F auid>=1000 -F auid!=unset 2. Run the following command to verify a rule exists in a rules file: # grep -Ps -- '^\h*[^#
]+\h*/usr/bin/kmod' /etc/audit/rules.d/*.rules Example output: /etc/audit/rules.d/50-kernel_modules.rules:-a always,exit -F arch=b64 -S all -F path=/usr/bin/kmod -F perm=x -F auid>=1000 -F auid!=unset -k kernel_modules Symlink audit Run the following script to audit if the symlinks kmod accepts are indeed pointing at it: Internal Only - General #!/usr/bin/env bash { a_files=("/usr/sbin/lsmod" "/usr/sbin/rmmod" "/usr/sbin/insmod" "/usr/sbin/modinfo" "/usr/sbin/modprobe" "/usr/sbin/depmod") for l_file in "${a_files[@]}"; do if [ "$(readlink -f "$l_file")" = "$(readlink -f /bin/kmod)" ]; then printf "OK: "$l_file"
" else printf "Issue with symlink for file: "$l_file"
" fi done } Verify the output states OK. If there is a symlink pointing to a different location it should be investigated

Rule.fixtext:
Note The following scripts will set the group to either audit or root based on the existence of the group audit. If the group audit doesn't exist, or the log_group parameter is already set to root, the appropriate group is determined to be the group root Run the following script to configure the audit log files to be owned by appropriate group:
#!/usr/bin/env bash
{
l_group=""; grep -Pq '^audit:' /etc/group && l_group="audit"
[ -z "$l_group" ] || [ "$(awk -F= '$1~/^\s*log_group\s*$/{print $2}'
/etc/audit/auditd.conf | xargs)" = root ] && l_group="root"
find $(dirname $(awk -F"=" '/^\s*log_file\s*=\s*/ {print $2}'
/etc/audit/auditd.conf | xargs)) -type f \( ! -group root -a ! -group audit
\) -exec chgrp "$l_group" {} +
}
Run the following script to configure the audit log files to be owned by the audit appropriate group:
#!/usr/bin/env bash
{
l_group=""; grep -Pq '^audit:' /etc/group && l_group="audit"
[ -z "$l_group" ] || [ "$(awk -F= '$1~/^\s*log_group\s*$/{print $2}'
/etc/audit/auditd.conf | xargs)" = root ] && l_group="root"
chgrp "$l_group" /var/log/audit/
}
Run the following script to set the log_group parameter in the audit configuration file to log_group = <appropriate_group>:
#!/usr/bin/env bash
{
l_group=""; grep -Pq '^audit:' /etc/group && l_group="audit"
[ -z "$l_group" ] || [ "$(awk -F= '$1~/^\s*log_group\s*$/{print $2}'
/etc/audit/auditd.conf | xargs)" = root ] && l_group="root"
sed -ri 's/^\s*#?\s*log_group\s*=\s*\S+(\s*#.*)?.*$/log_group =
'"$l_group"'\1/' /etc/audit/auditd.conf
}
Run the following command to restart the audit daemon to reload the configuration file:
# systemctl restart auditd

check.check-content:
Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_uid; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate UID: \"$l_uid\" Users: \"$(awk -F: '($3 == n) {
print $1 }' n=$l_uid /etc/passwd | xargs)\""
fi
done < <(cut -f3 -d":" /etc/passwd | sort -n | uniq -c)
}

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_gid; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate GID: \"$l_gid\" Groups: \"$(awk -F: '($3 == n) {
print $1 }' n=$l_gid /etc/group | xargs)\""
fi
done < <(cut -f3 -d":" /etc/group | sort -n | uniq -c)
}

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_user; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate User: \"$l_user\" Users: \"$(awk -F: '($1 == n) {
print $1 }' n=$l_user /etc/passwd | xargs)\""
fi
done < <(cut -f1 -d":" /etc/passwd | sort -n | uniq -c)
}

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_group; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate Group: \"$l_group\" Groups: \"$(awk -F: '($1 ==
n) { print $1 }' n=$l_group /etc/group | xargs)\""
fi
done < <(cut -f1 -d":" /etc/group | sort -n | uniq -c)
}
